#!/usr/bin/env python3
"""mkfont.py - build src/gen/font.a99 from assets/font5x8.bdf.

The font is X11's misc-fixed 5x8 (public domain: "Public domain font.
Share and enjoy.").  Glyphs for ASCII 32-126 are placed in the left six
bits of each pattern byte (T80 shows bits 7-2), shifted one pixel right
so each 4-pixel letter sits between one blank column on the left and
one on the right of its 6-pixel cell.  95 glyphs x 8 bytes."""
import re, sys
bdf = open('assets/font5x8.bdf').read()
out = ['* font.a99 - GENERATED by tools/mkfont.py from assets/font5x8.bdf.',
       '* Do not edit: rerun the tool.  95 glyphs (ASCII 32-126), 8 bytes each.',
       'FONT']
glyphs = {}
# Glyphs redrawn for TXA (in the BDF's own bit positions, before the shift):
# the font's period is a plus-shaped dot reaching into the descender row,
# which reads as a comma at 80 columns; TXA's is a square dot on the baseline.
OVERRIDE = {'.': [0x00, 0x00, 0x00, 0x00, 0x00, 0x60, 0x60, 0x00]}
for code in range(32, 127):
    m = re.search(r'ENCODING %d\n.*?BBX (-?\d+) (-?\d+) (-?\d+) (-?\d+)\nBITMAP\n(.*?)ENDCHAR' % code, bdf, re.S)
    w, h, xo, yo = map(int, m.group(1, 2, 3, 4))
    rows = [int(l, 16) for l in m.group(5).split()]
    cell = [0] * 8
    top = 7 - (h + yo)
    for i, r in enumerate(rows):
        y = top + i
        if 0 <= y < 8:
            cell[y] = (r >> (xo + 1)) & 0xFC   # one pixel right, keep 6 bits
    if chr(code) in OVERRIDE:
        cell = [(r >> 1) & 0xFC for r in OVERRIDE[chr(code)]]
    glyphs[code] = cell
    out.append('       BYTE ' + ','.join('>%02X' % b for b in cell) + '   ' + repr(chr(code)))
open('src/gen/font.a99', 'w').write('\n'.join(out) + '\n')
if '--show' in sys.argv:
    for c in 'Agjy|_':
        print(c); [print(format(b, '08b').replace('0', '.').replace('1', '#')) for b in glyphs[ord(c)]]
